import {createSearch} from './search-core.mjs';
import {loadCatalog} from './catalog-loader.mjs';
import {initializeAppearance} from './appearance.mjs';
let storage;try{storage=localStorage;}catch{}initializeAppearance(document,storage);
const $=id=>document.getElementById(id);
let engine,catalog,area='',page=0,suggestions=[],active=-1,timer,loading=false;
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function notify(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').hidden=true,6000);}
function options(){return {query:$('search').value,area,publisher:$('publisher').value,type:$('type').value,access:$('access').value,region:$('region').value,sort:$('sort').value,page};}
function closeSuggestions(){suggestions=[];active=-1;$('suggestions').hidden=true;$('search').setAttribute('aria-expanded','false');$('search').removeAttribute('aria-activedescendant');}
function selectArea(value){area=value;for(const b of $('areas').children)b.setAttribute('aria-pressed',String(b.dataset.area===area));$('selection-label').textContent=area||'All subject areas';search();}
function showAreas(){const values=[['',catalog.records.length],...engine.facets.areas];$('areas').replaceChildren();for(const [value,count]of values){const b=node('button',undefined,'area-button');b.type='button';b.dataset.area=value;b.setAttribute('aria-pressed',String(value===area));b.append(node('span',value||'All frameworks & standards'),node('span',count.toLocaleString()));b.onclick=()=>selectArea(value);$('areas').append(b);}}
function populate(id,values,label){const select=$(id),old=select.value;select.replaceChildren(new Option(label,''));for(const [value,count]of values)select.append(new Option(`${value} (${count})`,value));if(old&&!values.some(([v])=>v===old))select.append(new Option(old+' (not in refreshed catalog)',old));select.value=old;select.disabled=false;}
function sourceLink(text,url,cls){const link=node('a',text,cls);link.href=url;link.target='_blank';link.rel='noopener noreferrer';return link;}
function render(result){page=result.page;$('results').replaceChildren();$('results').setAttribute('aria-busy','false');$('result-count').textContent=result.total+' resources found';$('related').hidden=!result.related;$('results-heading').textContent=$('search').value?`Results for “${$('search').value}”`:'Frameworks & standards';
  if(!result.items.length){const box=node('div',undefined,'empty');box.append(node('h3','Try a broader search.'),node('p','Reset filters, use a shorter word, or try the framework abbreviation. Zero results does not prove no relevant framework exists.'));const b=node('button','Reset search and filters','quiet');b.onclick=reset;box.append(b);$('results').append(box);}
  for(const r of result.items){const card=node('article',undefined,'publication');card.dataset.id=r.id;const top=node('div',undefined,'publication-top');top.append(node('span',r.type,'series-tag'),node('span',r.publisher));const h=node('h3');h.append(sourceLink(r.title,r.url));card.append(top,h,node('p',r.summary,'abstract'));const tags=node('div',undefined,'tags');for(const tag of [r.access,...r.areas])tags.append(node('span',tag,'tag'));card.append(tags);const bottom=node('div',undefined,'publication-bottom');bottom.append(node('span','Publisher reference · Verify edition and applicability'),sourceLink('Open official source ↗',r.url,'source-link'));card.append(bottom);const details=node('details',undefined,'details');details.append(node('summary','Edition, scope & access notes'),node('p','Edition: '+r.edition),node('p','Region/context: '+r.regions.join(' · ')),node('p','Type: '+r.type+'. This category is not a declaration of legal applicability.'),node('p','Access describes the reference material. Certification, professional assessment, training or licensed documents may cost separately. No purchase is made through this app.'),node('p','Source: '+r.url));card.append(details);$('results').append(card);}
  const pages=Math.max(1,Math.ceil(result.total/result.pageSize));$('page-label').textContent=`Page ${page+1} of ${pages}`;$('previous').disabled=page===0;$('next').disabled=page+1>=pages;document.body.dataset.ready='true';
}
function search(resetPage=true){if(!engine)return;if(resetPage)page=0;closeSuggestions();$('clear-search').hidden=!$('search').value;render(engine.search(options()));}
function showSuggestions(){if(!engine)return;const values=engine.suggest($('search').value,options());suggestions=values;active=-1;$('suggestions').replaceChildren();if(!values.length){closeSuggestions();return;}values.forEach((s,i)=>{const li=node('li');li.id='suggestion-'+i;li.setAttribute('role','option');li.setAttribute('aria-selected','false');li.append(node('span',s.label,'suggest-label'),node('span',s.detail,'suggest-detail'));li.addEventListener('pointerdown',e=>e.preventDefault());li.onclick=()=>choose(i);$('suggestions').append(li);});$('suggestions').hidden=false;$('search').setAttribute('aria-expanded','true');}
function choose(i){const s=suggestions[i];if(!s)return;if(s.type==='area'){$('search').value='';selectArea(s.value);}else{$('search').value=s.value;search();}$('search').focus();}
function reset(){area='';for(const id of ['search','publisher','type','access','region'])$(id).value='';$('sort').value='relevance';selectArea('');$('search').focus();}
async function refresh(){if(loading)return;loading=true;$('refresh').disabled=true;$('refresh').textContent='Refreshing…';try{const next=await loadCatalog(),nextEngine=createSearch(next.records);catalog=next;engine=nextEngine;for(const [id,key,label]of [['publisher','publishers','All publishers'],['type','types','All resource types'],['access','access','All access types'],['region','regions','All regions']])populate(id,engine.facets[key],label);showAreas();$('search').disabled=false;$('search-button').disabled=false;$('catalog-count').textContent=catalog.records.length+' curated resources';$('catalog-release').textContent=engine.facets.publishers.length+' publishers · Catalog assembled '+new Date(catalog.meta.assembledAt).toLocaleDateString();$('coverage-text').textContent=catalog.meta.coverage;$('maintenance-text').textContent=catalog.meta.maintenance;$('coverage-details').replaceChildren();for(const [label,value]of [['Resources',String(catalog.records.length)],['Publishers',String(engine.facets.publishers.length)],['Subject groups',String(engine.facets.areas.length)],['Edition status','Verify current editions at official publisher links; some links open family directories.']])$('coverage-details').append(node('dt',label),node('dd',value));search();notify('Published catalog loaded. Your search and filters are kept.');}catch{notify('Catalog refresh failed. Previously loaded results remain available.');if(!engine){$('results').replaceChildren(node('div','The catalog could not be loaded. Reload or ask the owner to verify the catalog file.','error'));$('result-count').textContent='Catalog unavailable';$('results').setAttribute('aria-busy','false');}}finally{loading=false;$('refresh').disabled=false;$('refresh').textContent='↻ Refresh catalog';}}
$('search-form').onsubmit=e=>{e.preventDefault();if(active>=0)choose(active);else search();};
$('search').addEventListener('input',()=>{clearTimeout(timer);closeSuggestions();timer=setTimeout(()=>{search();showSuggestions();},140);});
$('search').addEventListener('keydown',e=>{if(e.key==='Escape'){closeSuggestions();return;}if(!suggestions.length)return;if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();active=e.key==='ArrowDown'?(active+1)%suggestions.length:(active-1+suggestions.length)%suggestions.length;for(let i=0;i<suggestions.length;i++)$('suggestion-'+i).setAttribute('aria-selected',String(i===active));$('search').setAttribute('aria-activedescendant','suggestion-'+active);$('suggestion-'+active).scrollIntoView({block:'nearest'});}else if(e.key==='Enter'&&active>=0){e.preventDefault();choose(active);}});
$('search').onblur=()=>setTimeout(closeSuggestions,150);$('clear-search').onclick=()=>{$('search').value='';search();$('search').focus();};
for(const b of document.querySelectorAll('[data-query]'))b.onclick=()=>{$('search').value=b.dataset.query;search();$('search').focus();};
for(const id of ['publisher','type','access','region','sort'])$(id).onchange=()=>search();
$('reset').onclick=reset;$('previous').onclick=()=>{page--;search(false);$('results-heading').scrollIntoView({block:'start'});};$('next').onclick=()=>{page++;search(false);$('results-heading').scrollIntoView({block:'start'});};
$('about').onclick=$('coverage-button').onclick=()=>$('coverage').showModal();$('close-coverage').onclick=()=>$('coverage').close();$('refresh').onclick=refresh;
$('share').onclick=async()=>{if(['127.0.0.1','localhost'].includes(location.hostname)){notify('This preview is local. Share the published website link, not localhost.');return;}try{await navigator.clipboard.writeText(location.origin+location.pathname);notify('Website link copied. Viewer access still follows the site’s sharing policy.');}catch{notify('Copy the website address from your browser’s address bar.');}};
refresh();
